// Elegir el mejor match y evaluar el ICP ANTES de gastar creditos.
const ICP_MIN = 15;
const ICP_MAX = 80;
const NAICS_OK = ['311','322','325','326','332','333','335','336'];
const AMBA = ['buenos aires','ciudad autonoma de buenos aires','caba','capital federal','san isidro','vicente lopez','tigre','san fernando','pilar','escobar','malvinas argentinas','general san martin','san martin','tres de febrero','moron','hurlingham','ituzaingo','la matanza','merlo','moreno','avellaneda','lanus','quilmes','lomas de zamora','esteban echeverria','ezeiza','berazategui','florencio varela'];

const out = [];

for (const item of $input.all()) {
  const cuenta = $('Una cuenta por vez').first().json;
  const orgs = item.json?.organizations || [];

  if (orgs.length === 0) {
    out.push({ json: { ...cuenta, estado: 'DESCARTADA', motivo_descarte: 'SIN_DATO', nota_a1: 'Sin match en Apollo. Candidata para padron de camara (ADIMRA/CADIEEL).' } });
    continue;
  }

  // Mejor match por similitud de nombre
  const norm = s => (s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9 ]/g,'').replace(/\b(sa|srl|sas|sacif|saic|sca|sh)\b/g,'').trim();
  const target = norm(cuenta.empresa);
  const org = orgs.sort((a,b) => {
    const sa = norm(a.name) === target ? 2 : (norm(a.name).includes(target) || target.includes(norm(a.name)) ? 1 : 0);
    const sb = norm(b.name) === target ? 2 : (norm(b.name).includes(target) || target.includes(norm(b.name)) ? 1 : 0);
    return sb - sa;
  })[0];

  const empleados = org.estimated_num_employees ?? null;
  const naics = (org.naics_codes || []).map(c => String(c).substring(0,3));
  const ubic = `${org.city || ''} ${org.state || ''}`.toLowerCase();

  const base = {
    ...cuenta,
    apollo_org_id: org.id,
    dominio: org.primary_domain || org.website_url || '',
    empleados,
    industria_naics: (org.naics_codes || []).join(','),
    anio_fundacion: org.founded_year || null,
    linkedin_empresa: org.linkedin_url || '',
    ciudad_apollo: org.city || '',
    provincia_apollo: org.state || ''
  };

  // ---- Filtros que protegen los creditos ----
  if (empleados !== null && (empleados < ICP_MIN || empleados > ICP_MAX)) {
    out.push({ json: { ...base, estado: 'DESCARTADA', motivo_descarte: 'TAMANO', nota_a1: `${empleados} empleados, fuera del rango ${ICP_MIN}-${ICP_MAX}` } });
    continue;
  }
  if (naics.length > 0 && !naics.some(c => NAICS_OK.includes(c))) {
    out.push({ json: { ...base, estado: 'DESCARTADA', motivo_descarte: 'RUBRO', nota_a1: `NAICS ${naics.join(',')} fuera del ICP` } });
    continue;
  }
  if (ubic.trim() && !AMBA.some(z => ubic.includes(z))) {
    out.push({ json: { ...base, estado: 'DESCARTADA', motivo_descarte: 'ZONA', nota_a1: `HQ en ${ubic.trim()}, fuera de AMBA` } });
    continue;
  }

  // ---- Score del ICP con datos reales ----
  let score = 0;
  if (empleados !== null && empleados >= ICP_MIN && empleados <= ICP_MAX) score += 3;
  if (naics.some(c => NAICS_OK.includes(c))) score += 3;
  if (AMBA.some(z => ubic.includes(z))) score += 2;
  if (base.dominio) score += 1;

  out.push({ json: { ...base, score_icp_real: score, estado: 'APTA_PARA_REVELAR' } });
}

return out;

