// Elegir un decisor por cuenta y cruzar contra supresiones.
const PRIORIDAD = [
  ['owner','founder','dueno','socio gerente','ceo','gerente general','director general'],
  ['gerente administrativo','administracion y finanzas','cfo','director financiero'],
  ['gerente de operaciones','gerente de planta','jefe de planta','gerente de produccion']
];
const ROL_GENERICO = /^(info|ventas|administracion|contacto|comercial|compras)@/i;

const supresiones = new Set(
  $('Leer supresiones').all().map(i => (i.json.email || '').toLowerCase())
);

const out = [];

for (const item of $input.all()) {
  const cuenta = $('¿Pasó el filtro?').first().json;
  const people = item.json?.people || item.json?.contacts || [];

  const validos = people.filter(p =>
    p.email &&
    p.email_status === 'verified' &&
    !ROL_GENERICO.test(p.email) &&
    !supresiones.has(p.email.toLowerCase())
  );

  if (validos.length === 0) {
    out.push({ json: { ...cuenta, estado: 'SIN_DECISOR', nota_a1: 'Sin email verificado. Derivar a cola de llamada telefonica (creditos de direct dial).' } });
    continue;
  }

  const rank = p => {
    const t = (p.title || '').toLowerCase();
    for (let i = 0; i < PRIORIDAD.length; i++) {
      if (PRIORIDAD[i].some(k => t.includes(k))) return i;
    }
    return 99;
  };
  const d = validos.sort((a, b) => rank(a) - rank(b))[0];

  const t = (d.title || '').toLowerCase();
  let persona = 'ADMIN';
  if (PRIORIDAD[0].some(k => t.includes(k))) persona = 'DUENO';
  else if (PRIORIDAD[2].some(k => t.includes(k))) persona = 'PLANTA';

  out.push({ json: {
    ...cuenta,
    estado: 'ENRIQUECIDA',
    decisor_nombre: `${d.first_name || ''} ${d.last_name || ''}`.trim(),
    decisor_cargo: d.title || '',
    decisor_email: d.email,
    decisor_linkedin: d.linkedin_url || '',
    decisor_telefono: d.phone_numbers?.[0]?.sanitized_number || '',
    persona,
    enriquecida_at: new Date().toISOString()
  }});
}

return out;
